## Building a Text Search

### Finding First Occurrence

```xiom
fn find_first(text: Str, pattern: Str) -> Option[Int] {
  if pattern.len() == 0 || pattern.len() > text.len() {
    return Option.None;
  };

  let mut i = 0;
  while i <= text.len() - pattern.len() {
    let mut matched = true;
    let mut j = 0;
    while j < pattern.len() {
      if text.get(i + j).unwrap() != pattern.get(j).unwrap() {
        matched = false;
        break;
      };
      j += 1;
    };
    if matched {
      return Option.Some(i);
    };
    i += 1;
  };
  Option.None
}
```

### Finding All Occurrences

```xiom
fn find_all(text: Str, pattern: Str) -> Vec[Int] {
  let mut positions: Vec[Int] = Vec[Int].new();
  let mut i = 0;
  while i <= text.len() - pattern.len() {
    let mut matched = true;
    let mut j = 0;
    while j < pattern.len() {
      if text.get(i + j).unwrap() != pattern.get(j).unwrap() {
        matched = false;
        break;
      };
      j += 1;
    };
    if matched {
      positions.push(i);
    };
    i += 1;
  };
  positions
}
```

### Case-Insensitive Search

```xiom
fn matches_at(text: Str, pattern: Str, start: Int) -> Bool {
  let mut j = 0;
  while j < pattern.len() {
    let tc = text.get(start + j).unwrap();
    let pc = pattern.get(j).unwrap();
    if to_lower(tc) != to_lower(pc) {
      return false;
    };
    j += 1;
  };
  true
}
```

