use xiom.io;
fn find_all(text: Str, pattern: Str) -> Vec[Int] {
  var positions: Vec[Int] = Vec[Int].new();
  if pattern.len() == 0 { return positions; };
  var i = 0;
  while i + pattern.len() <= text.len() {
    var matched = true;
    var j = 0;
    while j < pattern.len() {
      if text.char_at(i + j) != pattern.char_at(j) {
        matched = false;
        break;
      };
      j += 1;
    };
    if matched { positions.push(i); };
    i += 1;
  };
  positions
}

fn main() -> Int {
  let positions = find_all("this is a test and this is fun", "is");
  var i = 0;
  while i < positions.len() {
    io.println(positions.get(i).unwrap().to_str());
    i += 1;
  };
  return 0;
}
